'use strict';
const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('cs-CZ', {style:'currency',currency:'CZK',maximumFractionDigits:0}).format(value);
const normalize = value => String(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const labels = {capsules:'Kapsle & tobolky',elixirs:'Bylinné elixíry',superfoods:'Superpotraviny',other:'Další péče'};
const storage = {get(key, fallback){try{return JSON.parse(localStorage.getItem(key)) ?? fallback;}catch{return fallback;}},set(key,value){try{localStorage.setItem(key, JSON.stringify(value));}catch{/* The shop also works with session-only state. */}}};
let products = [], filter = 'all', visibleCount = 8, detailQty = 1, detailId = null, toastTimer;
let cart = storage.get('mijoli-cart-v1', []), favorites = storage.get('mijoli-favorites-v1', []);
if(!Array.isArray(cart)) cart=[];
if(!Array.isArray(favorites)) favorites=[];
let checkout = {step:1, fields:{country:'Česká republika'}, shipping:'address', payment:'transfer'};
const byId = id => products.find(p => p.id === Number(id));
const cartTotal = () => cart.reduce((sum,item) => sum + (byId(item.id)?.price || 0) * item.qty,0);
const cartCount = () => cart.reduce((sum,item) => sum + item.qty,0);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2700);}
function openDialog(id){const dialog=document.getElementById(id);$$('dialog[open]').forEach(d=>d.close());dialog.showModal();dialog.scrollTop=0;}
function closeDialog(button){button.closest('dialog')?.close();}
function persist(){storage.set('mijoli-cart-v1',cart);storage.set('mijoli-favorites-v1',favorites);updateCounters();}
function updateCounters(){const count=cartCount();$$('.cart-count').forEach(e=>e.textContent=count);$('.cart-button').setAttribute('aria-label',`Otevřít košík, ${count} položek`);$('.favorite-count').textContent=favorites.length;$('.favorite-count').hidden=!favorites.length;$$('.favorite-toggle').forEach(b=>{const saved=favorites.includes(Number(b.dataset.id));b.classList.toggle('is-saved',saved);b.setAttribute('aria-pressed',String(saved));const p=byId(b.dataset.id);b.setAttribute('aria-label',`${saved?'Odebrat z oblíbených':'Uložit do oblíbených'}: ${p?.name || ''}`);});}
function saveFavorite(id){id=Number(id);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persist();if(filter==='favorites')renderProducts();toast(favorites.includes(id)?'Uloženo do vašeho výběru ♡':'Produkt odebrán z oblíbených');}
function addToCart(id,qty=1){const p=byId(id);if(!p?.inStock)return;const existing=cart.find(i=>i.id===p.id);const requested=Math.max(1,Math.min(99,Number(qty)||1));if(existing)existing.qty=Math.min(99,existing.qty+requested);else cart.push({id:p.id,qty:requested});persist();renderCart();toast(`${p.name} je ve vašem košíku`);}
function changeQuantity(id,change){const item=cart.find(i=>i.id===Number(id));if(!item)return;item.qty+=change;if(item.qty<1)cart=cart.filter(i=>i!==item);else item.qty=Math.min(99,item.qty);persist();renderCart();}
function card(p,index){return `<article class="product-card"><div class="product-image-wrap"><span class="product-badge">${p.imageMissing?'Fotografie se připravuje':index===0&&filter==='all'?'NÁŠ TIP':esc(p.brand)}</span><button class="icon-button favorite-toggle ${favorites.includes(p.id)?'is-saved':''}" data-action="favorite" data-id="${p.id}" aria-label="Uložit do oblíbených: ${esc(p.name)}" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button><button class="product-image-button" data-action="product" data-id="${p.id}" aria-label="Zobrazit ${esc(p.name)}"><img src="${esc(p.image)}" alt="${esc(p.fullName)}" loading="lazy" width="300" height="360"></button></div><p class="product-category">${esc(labels[p.category]||'Doplňky stravy')}</p><h3 class="product-title"><button data-action="product" data-id="${p.id}">${esc(p.name)}</button></h3><p class="product-package">${esc(p.package||p.brand)}</p><div class="product-bottom"><div><span class="product-price">${money(p.price)}</span><span class="product-availability ${p.inStock?'':'unavailable'}">${p.inStock?'● Skladem':'Momentálně nedostupné'}</span></div><button class="add-button" data-action="add" data-id="${p.id}" aria-label="Přidat ${esc(p.name)} do košíku" ${p.inStock?'':'disabled'}>${icon('plus')}</button></div></article>`;}
function getFiltered(){let list=products.filter(p=>filter==='all'||(filter==='favorites'?favorites.includes(p.id):p.category===filter));const sort=$('#sort').value;if(sort==='price-asc')list.sort((a,b)=>a.price-b.price);if(sort==='price-desc')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'cs'));return list;}
function renderProducts(){const list=getFiltered();$('#products-grid').innerHTML=list.length?list.slice(0,visibleCount).map(card).join(''):`<div class="empty-state">${icon(filter==='favorites'?'heart':'leaf')}<h3>${filter==='favorites'?'Váš výběr teprve rozkvete.':'Tady je zatím klid.'}</h3><p>${filter==='favorites'?'Klepněte na srdíčko u produktu a vraťte se k němu kdykoliv.':'Prohlédněte si další kategorie v našem výběru.'}</p><button class="button button-outline" data-filter="all">Prohlédnout produkty ↗</button></div>`;$('#shown-count').textContent=`Zobrazeno ${Math.min(visibleCount,list.length)} z ${list.length} produktů`;$('#show-more').hidden=visibleCount>=list.length;$('#total-count').textContent=products.length;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter));});$('.favorites-tab').hidden=filter!=='favorites';updateCounters();}
function setFilter(next){filter=next;visibleCount=8;renderProducts();}
function openProduct(id){const p=byId(id);if(!p)return;detailId=p.id;detailQty=1;$('#product-detail').innerHTML=`<div class="product-detail-layout"><div class="detail-image"><img src="${esc(p.image)}" alt="${esc(p.fullName)}"></div><div class="detail-copy"><p class="eyebrow">${esc(p.brand)} / ${esc(labels[p.category]||'Další péče')}</p><h2>${esc(p.name)}</h2><p class="detail-package">${esc(p.package)}</p><span class="product-availability ${p.inStock?'':'unavailable'}">${p.inStock?'● Skladem v obchodě Mijoli':'Momentálně nedostupné'}</span><p class="detail-description">${esc(p.shortDescription||p.description)}</p><p class="detail-price">${money(p.price)}</p><div class="detail-add-row"><div class="quantity-control" aria-label="Počet kusů"><button data-action="detail-minus" aria-label="Snížit množství">−</button><span id="detail-qty" aria-live="polite">1</span><button data-action="detail-plus" aria-label="Zvýšit množství">+</button></div><button class="button button-dark" data-action="detail-add" ${p.inStock?'':'disabled'}>${p.inStock?'Přidat do košíku':'Není skladem'} ${icon('bag')}</button></div><div class="detail-accordion"><details><summary>O produktu</summary><p>${esc(p.description||p.shortDescription)}</p></details><details><summary>Složení</summary><p>${esc(p.ingredients||'Úplné složení najdete v aktuálním detailu produktu v obchodě Mijoli.')}</p></details><details><summary>Doporučené užívání</summary><p>${esc(p.use||'Řiďte se dávkováním na obalu výrobku. Úplné informace najdete v obchodě Mijoli.')}</p></details><details><summary>Upozornění a skladování</summary><p>${esc([p.warning,p.storage].filter(Boolean).join('\n\n')||'Před použitím si přečtěte informace na obalu.')}</p></details></div><a class="detail-source" href="${esc(p.url)}" target="_blank" rel="noopener">Úplné informace a skutečný nákup v obchodě Mijoli ↗</a><small class="detail-source" style="text-decoration:none">${p.imageMissing?'Fotografie produktu zatím není ve zdrojovém katalogu. ':''}Ceny a dostupnost převzaty ze Shoptetu. Náhled neodesílá objednávky.</small></div></div>`;openDialog('product-dialog');}
function renderCart(){const root=$('#cart-content');if(!products.length){root.innerHTML='<p class="search-prompt">Načítáme váš košík…</p>';return;}if(!cart.length){root.innerHTML=`<div class="empty-state">${icon('bag')}<h3>Prostor pro něco dobrého.</h3><p>Váš košík je zatím prázdný.<br>Najděte si svůj každodenní rituál.</p><button class="button button-dark" data-action="continue-shopping">Objevit produkty ↗</button></div>`;return;}root.innerHTML=`<div class="cart-items">${cart.map(item=>{const p=byId(item.id);return `<article class="cart-item"><button class="cart-item-image" data-action="product" data-id="${p.id}" aria-label="Detail ${esc(p.name)}"><img src="${esc(p.image)}" alt="${esc(p.name)}"></button><div><h3>${esc(p.name)}</h3><small>${esc(p.package)}</small><div class="quantity-control"><button data-action="cart-minus" data-id="${p.id}" aria-label="Snížit počet ${esc(p.name)}">−</button><span>${item.qty}</span><button data-action="cart-plus" data-id="${p.id}" aria-label="Zvýšit počet ${esc(p.name)}" ${item.qty>=99?'disabled':''}>+</button></div></div><div class="cart-item-end"><span>${money(p.price*item.qty)}</span><button class="cart-remove" data-action="remove" data-id="${p.id}" aria-label="Odebrat ${esc(p.name)}">Odebrat</button></div></article>`;}).join('')}</div><div class="cart-summary"><div class="summary-row"><span>Produkty (${cartCount()} ks)</span><span>${money(cartTotal())}</span></div><div class="summary-row"><span>Doprava</span><span>V dalším kroku</span></div><div class="summary-row total"><strong>Mezisoučet</strong><strong>${money(cartTotal())}</strong></div><button class="button button-dark" data-action="checkout">Pokračovat k objednávce <span>↗</span></button><p class="demo-note">Toto je náhled. Objednávku si můžete nezávazně vyzkoušet — nic se neodesílá a nic neplatíte.</p><button class="cart-continue" data-close>Ještě se porozhlédnout</button></div>`;}
function searchProducts(){const query=normalize($('#search-input').value.trim());const matches=products.filter(p=>normalize([p.name,p.brand,p.package,labels[p.category],p.ingredients].join(' ')).includes(query));$('#search-results').innerHTML=query?(matches.length?`<p class="search-prompt">Nalezeno ${matches.length} ${matches.length===1?'produkt':matches.length<5?'produkty':'produktů'}${matches.length>8?' · zobrazeno prvních 8':''}</p>`+matches.slice(0,8).map(p=>`<button class="search-result" data-action="product" data-id="${p.id}"><img src="${esc(p.image)}" alt=""><div><strong>${esc(p.name)}</strong><small>${esc(p.package)} · ${p.inStock?'Skladem':'Nedostupné'}</small></div><span>${money(p.price)} ↗</span></button>`).join(''):'<div class="empty-state"><h3>Tohle jsme nenašli.</h3><p>Zkuste kratší název, jinou bylinu nebo kategorii.</p></div>'):'<p class="search-prompt">Zkuste třeba „Imunita“, „Vitamin“ nebo „elixír“.</p>';}
function checkoutProgress(){return `<div class="checkout-progress"><span class="${checkout.step===1?'active':''}">01 · Vaše údaje</span><span class="${checkout.step===2?'active':''}">02 · Doprava & platba</span><span class="${checkout.step===3?'active':''}">03 · Souhrn</span></div>`;}
function shippingCost(){return checkout.shipping==='address'?99:0;}
function renderCheckout(){const root=$('#checkout-content');$('#checkout-title').textContent='Už jen malý krok.';const note='<p class="demo-note">Zkušební objednávka. Žádná data se neodesílají, nevzniká objednávka ani platba. Pro vyzkoušení použijte smyšlené údaje.</p>';let body='';if(checkout.step===1){const fields=[['firstName','Jméno','text','given-name'],['lastName','Příjmení','text','family-name'],['email','E-mail','email','email'],['phone','Telefon','tel','tel'],['street','Ulice a číslo domu','text','street-address'],['city','Město','text','address-level2'],['zip','PSČ','text','postal-code']];body=`${note}<form id="checkout-form" class="checkout-form">${fields.map(([key,label,type,auto])=>`<label class="${key==='street'?'full':''}">${label} *<input name="${key}" type="${type}" autocomplete="${auto}" value="${esc(checkout.fields[key]||'')}" required maxlength="${key==='email'?120:80}" ${key==='phone'?'title="Zadejte telefon včetně alespoň 9 číslic"':''} ${key==='zip'?'pattern="[0-9]{3} ?[0-9]{2}" inputmode="numeric" title="Zadejte PSČ ve formátu 123 45"':''}></label>`).join('')}<label>Země<select name="country"><option>Česká republika</option></select></label><button class="button button-dark full" type="submit">Doprava a platba <span>→</span></button></form>`;}else if(checkout.step===2){body=`${note}<h3 class="checkout-subtitle">Jak by to k vám putovalo?</h3><div class="checkout-options"><label><input type="radio" name="shipping" value="address" ${checkout.shipping==='address'?'checked':''}><span>Kurýr na adresu<small>Ukázková doprava · doručení na zadanou adresu</small></span><b>99 Kč</b></label><label><input type="radio" name="shipping" value="pickup" ${checkout.shipping==='pickup'?'checked':''}><span>Osobní odběr<small>Ukázková možnost · místo se zatím nevybírá</small></span><b>Zdarma</b></label></div><h3 class="checkout-subtitle">Způsob platby</h3><div class="checkout-options"><label><input type="radio" name="payment" value="transfer" ${checkout.payment==='transfer'?'checked':''}><span>Bankovní převod<small>V náhledu nevznikají platební údaje</small></span><b>Zdarma</b></label><label><input type="radio" name="payment" value="card" ${checkout.payment==='card'?'checked':''}><span>Platba kartou<small>Ukázka výběru · žádná karta se nezadává</small></span><b>Zdarma</b></label></div><div class="checkout-actions"><button class="text-link" data-action="checkout-back">← Vaše údaje</button><button class="button button-dark" data-action="checkout-next">Zkontrolovat objednávku <span>→</span></button></div>`;}else{const f=checkout.fields;body=`${note}<div class="review-address"><strong>${esc(f.firstName)} ${esc(f.lastName)}</strong><br>${esc(f.street)}, ${esc(f.zip)} ${esc(f.city)}<br>${esc(f.email)} · ${esc(f.phone)}<br><br>${checkout.shipping==='address'?'Kurýr na adresu':'Osobní odběr (ukázka)'} · ${checkout.payment==='card'?'Platba kartou (ukázka)':'Bankovní převod (ukázka)'}</div><div class="review-items">${cart.map(i=>`<div class="summary-row"><span>${i.qty} × ${esc(byId(i.id).name)}</span><span>${money(byId(i.id).price*i.qty)}</span></div>`).join('')}</div><div class="summary-row"><span>Doprava (ukázková cena)</span><span>${money(shippingCost())}</span></div><div class="summary-row total"><strong>Celkem v náhledu</strong><strong>${money(cartTotal()+shippingCost())}</strong></div><div class="checkout-actions"><button class="text-link" data-action="checkout-back">← Doprava a platba</button><button class="button button-dark" data-action="checkout-finish">Dokončit ukázku <span>✓</span></button></div>`;}root.innerHTML=checkoutProgress()+body;$('#checkout-dialog').scrollTop=0;}
function finishCheckout(){if(!cart.length)return;$('#checkout-title').textContent='Váš rituál je připravený.';$('#checkout-content').innerHTML=`<div class="checkout-success"><div class="success-icon">${icon('check')}</div><p class="eyebrow">UKÁZKA DOKONČENA</p><h3>Takto by začal<br>váš příběh s Mijoli.</h3><p>Prošli jste celou objednávkou.<br>Žádná objednávka nebyla odeslána a nic se neplatilo.<br>Košík jsme vám ponechali pro další prohlížení.</p><button class="button button-dark" data-action="continue-shopping">Zpátky k objevování <span>↗</span></button></div>`;checkout={step:1,fields:{country:'Česká republika'},shipping:'address',payment:'transfer'};}
document.addEventListener('click',event=>{const target=event.target.closest('button,a');if(!target)return;if(target.hasAttribute('data-close')){closeDialog(target);return;}if(target.dataset.filter){setFilter(target.dataset.filter);return;}if(target.dataset.category){setFilter(target.dataset.category);$('.header nav').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');return;}const action=target.dataset.action,id=target.dataset.id;if(!action)return;switch(action){case'menu':{const nav=$('.header nav');nav.classList.toggle('open');target.setAttribute('aria-expanded',String(nav.classList.contains('open')));break;}case'search':openDialog('search-dialog');$('#search-input').value='';searchProducts();$('#search-input').focus();break;case'favorites':setFilter('favorites');$('#produkty').scrollIntoView({behavior:'smooth'});break;case'favorite':saveFavorite(id);break;case'product':openProduct(id);break;case'add':addToCart(id);break;case'cart':renderCart();openDialog('cart-dialog');break;case'cart-minus':changeQuantity(id,-1);break;case'cart-plus':changeQuantity(id,1);break;case'remove':cart=cart.filter(i=>i.id!==Number(id));persist();renderCart();break;case'detail-minus':detailQty=Math.max(1,detailQty-1);$('#detail-qty').textContent=detailQty;break;case'detail-plus':detailQty=Math.min(99,detailQty+1);$('#detail-qty').textContent=detailQty;break;case'detail-add':addToCart(detailId,detailQty);$('#product-dialog').close();openDialog('cart-dialog');break;case'continue-shopping':$$('dialog[open]').forEach(d=>d.close());$('#produkty').scrollIntoView({behavior:'smooth'});break;case'checkout':if(cart.length){checkout.step=1;renderCheckout();openDialog('checkout-dialog');}break;case'checkout-back':checkout.step=Math.max(1,checkout.step-1);renderCheckout();break;case'checkout-next':checkout.shipping=$('input[name=shipping]:checked').value;checkout.payment=$('input[name=payment]:checked').value;checkout.step=3;renderCheckout();break;case'checkout-finish':finishCheckout();break;case'privacy':openDialog('info-dialog');break;case'clear-data':cart=[];favorites=[];persist();renderProducts();renderCart();toast('Košík i oblíbené jsou vymazané.');break;}});
document.addEventListener('submit',event=>{if(event.target.id!=='checkout-form')return;event.preventDefault();const data=Object.fromEntries(new FormData(event.target));const empty=$$('input[required]',event.target).find(i=>!i.value.trim());if(empty){empty.setCustomValidity('Vyplňte prosím toto pole.');empty.reportValidity();empty.addEventListener('input',()=>empty.setCustomValidity(''),{once:true});return;}if(!/^\+?[\d\s()-]{9,20}$/.test(data.phone)||(data.phone.match(/\d/g)||[]).length<9){const phone=$('input[name=phone]',event.target);phone.setCustomValidity('Telefon musí obsahovat alespoň 9 číslic.');phone.reportValidity();phone.addEventListener('input',()=>phone.setCustomValidity(''),{once:true});return;}checkout.fields=data;checkout.step=2;renderCheckout();});
document.addEventListener('change',event=>{if(event.target.name==='shipping')checkout.shipping=event.target.value;if(event.target.name==='payment')checkout.payment=event.target.value;});
$('#search-input').addEventListener('input',searchProducts);
$('#sort').addEventListener('change',()=>{visibleCount=8;renderProducts();});
$('#show-more').addEventListener('click',()=>{visibleCount+=8;renderProducts();});
$$('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.header nav').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');}});
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el));}
async function init(){try{const response=await fetch('products.json');if(!response.ok)throw new Error('Catalog unavailable');products=await response.json();cart=cart.filter(i=>byId(i.id)?.inStock&&Number.isFinite(i.qty)&&i.qty>0).map(i=>({id:Number(i.id),qty:Math.min(99,Math.floor(i.qty))}));favorites=[...new Set(favorites.map(Number).filter(id=>byId(id)))];persist();renderProducts();renderCart();}catch(error){$('#products-grid').innerHTML='<div class="empty-state"><h3>Katalog se nepodařilo načíst.</h3><p>Zkuste obnovit stránku. Produkty najdete také ve stávajícím obchodě.</p><a class="button button-outline" href="https://784006.myshoptet.com/" target="_blank" rel="noopener">Otevřít Mijoli ↗</a></div>';$('#show-more').hidden=true;console.error('Mijoli: katalog nelze načíst.');}}
init();
